import 'server-only';
import { scrypt as scryptCb, timingSafeEqual } from 'node:crypto';

/** Format: scrypt$N$r$p$salt(base64)$hash(base64) — generated by scripts/hash-password.mjs. */
function scrypt(password: string, salt: Buffer, N: number, r: number, p: number, len: number): Promise<Buffer> {
  return new Promise((resolve, reject) =>
    scryptCb(password, salt, len, { N, r, p, maxmem: 256 * N * r }, (err, key) => (err ? reject(err) : resolve(key))),
  );
}

export async function verifyPassword(password: string, stored: string): Promise<boolean> {
  const m = /^scrypt\$(\d+)\$(\d+)\$(\d+)\$([^$]+)\$([^$]+)$/.exec(stored);
  if (!m) return false;
  const expected = Buffer.from(m[5]!, 'base64');
  if (expected.length < 16) return false;
  try {
    const got = await scrypt(password, Buffer.from(m[4]!, 'base64'), Number(m[1]), Number(m[2]), Number(m[3]), expected.length);
    return timingSafeEqual(got, expected);
  } catch {
    return false;
  }
}

/** Best-effort in-memory limiter (per server instance): 5 attempts per 5 minutes per key. */
const attempts = new Map<string, { n: number; reset: number }>();
export function rateLimit(key: string, max = 5, windowMs = 5 * 60_000): { ok: boolean; retryAfter: number } {
  const now = Date.now();
  const cur = attempts.get(key);
  if (!cur || cur.reset < now) {
    attempts.set(key, { n: 1, reset: now + windowMs });
    return { ok: true, retryAfter: 0 };
  }
  cur.n++;
  return cur.n > max ? { ok: false, retryAfter: Math.ceil((cur.reset - now) / 1000) } : { ok: true, retryAfter: 0 };
}
